import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// Font Loading
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const { fontFamily: interFamily } = loadInter();



export type InstagramNotificationProps = Record<string, any>;

const InstagramNotification: React.FC<InstagramNotificationProps> = ({
  backgroundColor = "#0F0F0F",
  transparentBackground = false,
  durationInSeconds = 10,
  iconColor = "#FFFFFF",
  badgeColor = "#FF004D",
  badgeTextColor = "#FFFFFF",
  targetNotificationCount = 999999,
  iconSizePercentage = 0.4,
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Derived dimensions
  const totalFrames = fps * durationInSeconds;
  const iconPx = width * iconSizePercentage;
  const badgeHeightPx = iconPx * 0.35;
  const badgeFontSizePx = badgeHeightPx * 0.55;

  // Colors & Transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animations
  const mainScale = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const badgeSpring = spring({
    frame: frame - 15,
    fps,
    config: { damping: 12, mass: 0.6 },
  });

  // Continuous subtle pulse on the badge to make it feel "active"
  const pulse = Math.sin((frame - 15) / 4) * 0.05 + 1;
  const badgeScale = Math.max(0, badgeSpring * pulse);

  // Exponential counting logic to simulate "indefinite" acceleration
  // We use Math.pow to make it start slow and speed up rapidly
  const countProgress = interpolate(
    frame - 20,
    [0, totalFrames - 20],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const exponentialProgress = Math.pow(countProgress, 3);
  const currentCount = Math.floor(
    interpolate(
      exponentialProgress,
      [0, 1],
      [0, targetNotificationCount]
    )
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: interFamily,
      }}
    >
      {/* Container wrapper for relative positioning */}
      <div
        style={{
          position: "relative",
          width: iconPx,
          height: iconPx,
          transform: `scale(${mainScale})`,
          transition: "none",
        }}
      >
        {/* Instagram SVG Icon */}
        <svg
          viewBox="0 0 24 24"
          width="100%"
          height="100%"
          fill="none"
          stroke={iconColor}
          strokeWidth="1.8"
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{ transition: "none" }}
        >
          <rect x="2" y="2" width="20" height="20" rx="5" ry="5" />
          <path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z" />
          <line x1="17.5" y1="6.5" x2="17.51" y2="6.5" />
        </svg>

        {/* Notification Badge */}
        <div
          style={{
            position: "absolute",
            top: 0,
            right: 0,
            // Offset it so the center of the badge sits near the top-right corner
            transform: `translate(25%, -25%) scale(${badgeScale})`,
            transformOrigin: "center center",
            backgroundColor: badgeColor,
            color: badgeTextColor,
            minWidth: badgeHeightPx,
            height: badgeHeightPx,
            borderRadius: badgeHeightPx / 2,
            padding: `0 ${badgeHeightPx * 0.3}px`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            boxShadow: "0px 10px 30px rgba(0,0,0,0.3)",
            transition: "none",
            boxSizing: "border-box",
            // Border matches background color of main canvas to create a "cutout" effect if solid
            border: transparentBackground ? `8px solid transparent` : `8px solid ${backgroundColor}`,
          }}
        >
          <span
            style={{
              fontSize: badgeFontSizePx,
              fontWeight: 800,
              letterSpacing: "-0.03em",
              lineHeight: 1,
              marginTop: "2%", // Optical alignment for standard numbers
              transition: "none",
            }}
          >
            {currentCount.toLocaleString("en-US")}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default InstagramNotification;